"""Regenerate supabase/migrations/0001_init.sql from the SQLAlchemy models (tables) + supabase/policies.sql (RLS).

    python scripts/dump_schema.py
"""

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "backend"))

from sqlalchemy.dialects import postgresql  # noqa: E402
from sqlalchemy.schema import CreateIndex, CreateTable  # noqa: E402

from app import models  # noqa: E402,F401
from app.db import Base  # noqa: E402

dialect = postgresql.dialect()
out = [
    "-- GENERATED by backend/scripts/dump_schema.py from backend/app/models.py. Do not edit by hand.",
    "create extension if not exists vector;",
    "",
]
for table in Base.metadata.sorted_tables:
    ddl = str(CreateTable(table, if_not_exists=True).compile(dialect=dialect)).strip()
    out.append(ddl + ";")
    for idx in table.indexes:
        out.append(str(CreateIndex(idx, if_not_exists=True).compile(dialect=dialect)).strip() + ";")
    out.append("")

out.append("-- Approximate nearest-neighbour indexes for semantic search")
out.append("create index if not exists chunks_embedding_hnsw on chunks using hnsw (embedding vector_cosine_ops);")
out.append("create index if not exists decisions_embedding_hnsw on decisions using hnsw (embedding vector_cosine_ops);")
out.append("")
out.append((ROOT / "supabase" / "policies.sql").read_text(encoding="utf-8"))

target = ROOT / "supabase" / "migrations" / "0001_init.sql"
target.write_text("\n".join(out), encoding="utf-8")
print(f"wrote {target}")
